import { tags } from "typia";

/**
 * Summary view of a single security incident derived from security and
 * authentication logging tables.
 *
 * Each summary aggregates key data points from shopping_mall_security_events,
 * shopping_mall_auth_logs, shopping_mall_access_logs, or related logging models
 * to describe one security-relevant incident for quick review in lists and
 * dashboards.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallSecurityIncidentSummary = {
  /**
   * Stable identifier of the security incident within the reporting
   * subsystem. This may be a synthetic identifier that groups one or more
   * underlying log records into a single incident.
   */
  id: string;

  /**
   * Timestamp when this security incident was detected or considered to have
   * occurred. Uses ISO 8601 date-time format in UTC.
   */
  occurredAt: string & tags.Format<"date-time">;

  /**
   * High-level category that classifies the incident type, such as
   * authenticationAnomaly, accessPolicyViolation, suspectedFraud, or
   * integrationSecurityIssue.
   */
  category: string;

  /**
   * Severity level assigned to this incident based on detection rules or risk
   * assessment. Typical values include info, warning, and critical.
   */
  severity: string;

  /**
   * Short human-readable description of the incident for quick scanning in
   * list views and dashboards.
   */
  summary: string & tags.MaxLength<1024>;

  /**
   * Type of actor associated with this incident, if any. Indicates whether
   * the incident relates to a customer, seller, platform administrator, or an
   * anonymous/guest context.
   */
  principalType?: string | undefined;

  /**
   * Identifier of the principal associated with this incident when available.
   * May reference a customer, seller, or platform admin account, or be null
   * when the incident is not tied to a specific identity.
   */
  principalId?: string | undefined;

  /**
   * Source IP address associated with the incident, if captured by logging.
   * Useful for correlation and threat hunting workflows.
   */
  ipAddress?: string | undefined;

  /**
   * Session identifier associated with the incident when available, typically
   * referencing a customer, seller, or platform admin session context.
   */
  sessionId?: string | undefined;

  /**
   * Identifier of a related authentication log entry from
   * shopping_mall_auth_logs when this incident is rooted in authentication
   * behavior.
   */
  relatedAuthLogId?: string | undefined;

  /**
   * Identifier of a related access log entry from shopping_mall_access_logs
   * when this incident was detected from request/response patterns.
   */
  relatedAccessLogId?: string | undefined;

  /**
   * Identifier of the primary security event record from
   * shopping_mall_security_events that triggered this incident summary.
   */
  relatedSecurityEventId?: string | undefined;
};
